else {foreach(getDummyOrders() as $o)if((int)$o['user_id']===(int)$_SESSION['user_id'])$orders[]=$o;$orders=array_merge($_SESSION['demo_orders']??[],$orders);usort($orders,fn($a,$b)=>strcmp($b['created_at'],$a['created_at']));}
?>
<section class="section"><div class="container"><div class="page-header"><div><h1>Pesanan Saya</h1><p class="text-muted">Pantau status dan detail belanjamu.</p></div><a href="<?= BASE_URL ?>/buyer/" class="btn btn-outline">Belanja lagi</a></div><?php if(!$orders): ?><div class="empty-state"><span class="empty-icon">📋</span><h3>Belum ada pesanan</h3><p>Pesanan yang kamu buat akan muncul di sini.</p><a class="btn btn-primary" href="<?= BASE_URL ?>/buyer/">Mulai belanja</a></div><?php else: foreach($orders as $o): ?><article class="order-card"><header class="order-card-header"><div><div class="order-number"><?= sanitize($o['order_number']) ?></div><div class="order-date"><?= date('d M Y · H:i',strtotime($o['created_at'])) ?></div></div><span class="badge <?= statusBadge($o['status']) ?>"><?= statusLabel($o['status']) ?></span></header><div class="order-card-body"><?php foreach($o['items'] as $i): ?><div class="order-item"><span><?= sanitize($i['product_name']) ?> × <?= (int)$i['quantity'] ?></span><strong><?= formatRupiah($i['price']*$i['quantity']) ?></strong></div><?php endforeach; ?><p class="text-muted mt-2 mb-1">Kirim ke: <?= sanitize($o['shipping_address']??'') ?></p><p class="text-muted mb-1">Pembayaran: <?= sanitize($o['payment_method']??'') ?></p></div><footer class="order-card-footer"><span>Total pembayaran</span><strong class="order-total"><?= formatRupiah($o['total_amount']) ?></strong></footer></article><?php endforeach; endif; ?></div></section>
